arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel","exclude_archived":false,"limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'))
if d.get('ok'):
    for c in d['channels']:
        name=c.get('name','')
        if 'incident' in name.lower() or 'checkout' in name.lower() or 'outage' in name.lower():
            print(c['id'], '|', name, '| archived:', c.get('is_archived'), '| topic:', (c.get('topic') or {}).get('text',''))
else:
    print(d.get('error'))
"

